{
  "flowCount": 8,
  "flows": [
    {
      "name": "blockout_to_assets",
      "description": "Replace every blockout actor carrying tag (default Blockout) with the best-fitting StaticMesh under candidateFolder: lists the set, ranks the candidates by bounds, swaps each actor for its best match fitted to its bounds (fit, default uniform), then lists the replacements. Each replacement keeps a record, so level(restore_blockout) or the run's rollback puts the blockout back.",
      "stepCount": 4
    },
    {
      "name": "niagara_fire",
      "description": "Build a fire Niagara system from scratch (spawn rate, upward velocity, HDR orange colour) and verify it emits. A 0-to-1 best-practice starting point, not a demo. Lands at /Game/VFX/Fire/NS_Fire; override name/packagePath via params.",
      "stepCount": 7
    },
    {
      "name": "beacon",
      "description": "Demo - build a shrine scene from scratch: floor, pedestal, orb, five pillars, four materials (dark stone, brushed metal, warm stone, parameterized emissive), colored lights, and atmosphere",
      "stepCount": 56
    },
    {
      "name": "texture_bomb",
      "description": "Build a reusable MF_TextureBomb MaterialFunction (#491). Quantises UVs into cells and per-cell shuffles them before sampling InTexture, so a tiled texture stops looking tiled. Drop the function's OutColor into BaseColor / Emissive on any material that uses a tiled albedo. CellDensity input controls the cell frequency. Lives at /Game/Materials/Functions/MF_TextureBomb.",
      "stepCount": 14
    },
    {
      "name": "neon_shrine",
      "description": "Build the full Neon Shrine demo scene end-to-end (19 steps). Driven by the demo.step handler shipped with the bridge plugin. Leaves the editor on /Game/Demo/DemoLevel; run neon_shrine_cleanup to wipe it.",
      "stepCount": 19
    },
    {
      "name": "neon_shrine_cleanup",
      "description": "Wipe the Neon Shrine demo content. Switches the editor to /Game/MCP_Home first so you don't get stranded on Untitled.",
      "stepCount": 1
    },
    {
      "name": "playtest",
      "description": "Draft a PIE test script for a target with the flow model and save it. params: target (asset path or description), context? (what to test), profile?, name?, package_path?. Gathers the target Blueprint, its input mappings and the values PIE can watch, drafts with an agent step, checks the draft with pie(script_validate) and returns refusals to the model up to 2 times, then saves it with pie(script_create). Fails before drafting when target is a path that resolves to nothing, and with the last errors when every draft is refused. Needs a model: a daemon extension's provider, or ANTHROPIC_API_KEY.",
      "stepCount": 8
    },
    {
      "name": "outline",
      "description": "Read the outliner, then fail in the editor.",
      "stepCount": 2
    }
  ]
}

